{{pins}}
const int LEDS[4] = { LED_RED, LED_YELLOW, LED_GREEN, LED_BLUE };
const int BUTTONS[4] = { BUTTON_RED, BUTTON_YELLOW, BUTTON_GREEN, BUTTON_BLUE };
const int NOTES[4] = { 262, 330, 392, 523 };  // C, E, G and high C

void flash(int colour) {
  digitalWrite(LEDS[colour], HIGH);
  tone(BUZZER_PIN, NOTES[colour]);
  delay(300);
  digitalWrite(LEDS[colour], LOW);
  noTone(BUZZER_PIN);
  delay(100);
}

void setup() {
  for (int i = 0; i < 4; i++) {
    pinMode(LEDS[i], OUTPUT);
    pinMode(BUTTONS[i], INPUT_PULLUP);
  }
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
  randomSeed(analogRead(0));
}

void loop() {
  for (int i = 0; i < 4; i++) {
    flash(i);
  }
  delay(1000);
}

