{{pins}}
const int LEDS[4] = { LED_RED, LED_YELLOW, LED_GREEN, LED_BLUE };
const int BUTTONS[4] = { BUTTON_RED, BUTTON_YELLOW, BUTTON_GREEN, BUTTON_BLUE };
const int NOTES[4] = { 262, 330, 392, 523 };  // C, E, G and high C

int pattern[100];
int length = 0;

void flash(int colour) {
  digitalWrite(LEDS[colour], HIGH);
  tone(BUZZER_PIN, NOTES[colour]);
  delay(300);
  digitalWrite(LEDS[colour], LOW);
  noTone(BUZZER_PIN);
  delay(100);
}

void setup() {
  for (int i = 0; i < 4; i++) {
    pinMode(LEDS[i], OUTPUT);
    pinMode(BUTTONS[i], INPUT_PULLUP);
  }
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
  randomSeed(analogRead(0));
}

// Waits for a press and returns its colour (0 to 3).
int waitForPress() {
  while (true) {
    for (int i = 0; i < 4; i++) {
      if (digitalRead(BUTTONS[i]) == LOW) {
        flash(i);
        while (digitalRead(BUTTONS[i]) == LOW) { }  // wait for release
        return i;
      }
    }
  }
}

void gameOver() {
  Serial.print("Game over! You reached round ");
  Serial.println(length);
  tone(BUZZER_PIN, 150, 800);
  delay(2000);
  length = 0;
}

void loop() {
  // Simon adds a colour and shows the whole pattern.
  pattern[length] = random(0, 4);
  length++;
  Serial.print("Round ");
  Serial.println(length);
  delay(500);
  for (int i = 0; i < length; i++) {
    flash(pattern[i]);
  }
  // Now you copy it.
  for (int i = 0; i < length; i++) {
    if (waitForPress() != pattern[i]) {
      gameOver();
      return;
    }
  }
}
